-- ============================================================
--  ECCA — Asignar sexo automáticamente por nombre
--  Detecta por cualquier palabra del campo `nombre`
--  Ejecutar UNA sola vez tras crear la columna sexo
-- ============================================================

CREATE EXTENSION IF NOT EXISTS unaccent;

