SET sexo = 'M'
WHERE sexo IS NULL
  AND lower(unaccent(nombre)) ~ '\m(abril|adamaris|adilene|adriana|aide|aidee|ailin|aimee|alba|aleida|alejandra|alena|alicia|alina|alondra|altagracia|amalia|amparo|amira|amy|ana|anabel|anahi|anali|andrea|angela|angelica|angelina|angie|anita|annette|antonia|araceli|aracely|arcelia|areli|ariadna|ariana|arianna|arlett|arlette|armida|astrid|aurora|azalea|azucena|barbara|beatriz|belen|berenice|bertha|bianca|blanca|brenda|briseyda|camila|carla|carolina|catalina|cecilia|celia|citlali|citlaly|claudia|concepcion|consuelo|coral|corina|cristina|cynthia|daiana|daisy|dalia|dalila|danielle|daniela|danna|dayana|deisy|delia|denise|diana|dolores|dulce|edith|edna|elba|elda|elena|eliana|elisa|elizabeth|elsa|elvira|emilia|emiliana|emily|esperanza|esther|estela|estrella|eugenia|eva|evangelina|evelin|evelyn|fabiola|fernanda|fidelia|flor|florencia|florinda|frida|gabriela|genesis|georgina|gisela|gloria|graciela|griselda|guadalupe|hannah|hilda|hortensia|ileana|iliana|imelda|inés|ines|ingrid|irais|irene|irma|isabel|isela|itzel|ivette|ivonne|jacqueline|jade|janeth|janet|jazmin|jennifer|jenny|jessica|jessenia|jimena|joana|johana|johanna|josefina|juana|juanita|judith|julieta|julissa|julia|karen|karina|karla|katia|katya|keila|kelly|kenia|keren|keyla|kiara|kimberly|laura|leidy|leydi|lilian|liliana|lilia|lina|liseth|lissette|lizbeth|litzy|liz|lorena|lourdes|lucia|luisa|lupita|luz|luzma|lydia|mabel|magali|magaly|maira|maleny|manuela|marcela|margarita|mari|maria|mariana|mariangel|maricela|mariel|mariela|mariely|marla|marlen|marlene|marlenne|marlyn|martha|mary|marycruz|marysol|mayra|mayela|melanie|melina|melissa|melody|mercedes|michelle|minerva|miranda|miriam|mirna|mitzy|monika|montserrat|monica|nadia|nahomy|nallely|nanci|nancy|natalia|natasha|nazareth|nayeli|nidia|nikole|nieves|noemi|noemí|nora|noelia|norma|odette|ofelia|odalys|olimpia|olivia|ortencia|pamela|paola|patricia|paulina|penelope|perla|pilar|priscila|priscilla|raquel|rebeca|regina|remedios|reyna|rocio|romina|rosa|rosalba|rosalinda|rosalva|