-- ── 3. Verificar resultado ────────────────────────────────────
SELECT
  sexo,
  COUNT(*) AS total
FROM inscripciones
GROUP BY sexo
ORDER BY sexo NULLS LAST;

-- ── 4. Ver los que quedaron sin identificar ───────────────────
SELECT folio, nombre
FROM inscripciones
WHERE sexo IS NULL
ORDER BY nombre
LIMIT 50;
